<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{Save,Globe2,UserRound,Cpu,ShieldCheck,Activity}from'lucide-vue-next';import{api}from'../api';import{useAppStore}from'../stores/app';
const store=useAppStore(),form=reactive<any>({}),saving=ref(false),tab=ref('general'),current_password=ref(''),new_password=ref(''),confirm_password=ref('');onMounted(async()=>{if(!store.settings)await store.load();Object.assign(form,store.settings)});async function save(){if(new_password.value!==confirm_password.value)return ElMessage.error('两次输入的新密码不一致');saving.value=true;try{const r:any=await api('/api/settings',{method:'PUT',body:JSON.stringify({...form,current_password:current_password.value||null,new_password:new_password.value||null})});if(r.reauth_required){ElMessage.success('账号已更新，请重新登录');await store.logout()}else{Object.assign(store.settings!,r.settings);ElMessage.success('系统设置已保存')}}catch(e:any){ElMessage.error(e.message)}finally{saving.value=false}}
</script>
<template><section class="page settings-page"><header class="page-head"><div><p class="eyebrow">SYSTEM SETTINGS</p><h1>系统设置</h1><p>管理常规、刷新、安全、节点处理与自动测活。</p></div><el-button type="primary" :loading="saving" @click="save"><Save/>保存全部设置</el-button></header><div v-if="form.default_credentials" class="security-alert danger"><ShieldCheck/><div><b>必须修改默认密码</b><span>当前仍为默认凭据，公开部署前请立即修改。</span></div></div><div class="panel settings-tabs"><el-tabs v-model="tab" tab-position="left"><el-tab-pane label="常规" name="general"><div class="settings-pane"><section class="form-section"><div class="settings-title"><Globe2/><div><h2>站点与域名</h2><p>控制后台品牌和固定订阅地址。</p></div></div><label>系统名称<el-input v-model="form.site_name"/></label><label>公开访问地址<el-input v-model="form.public_base_url"/></label><div class="runtime-row"><span>监听端口</span><code>7777</code></div><div class="runtime-row"><span>持久化目录</span><code>/data</code></div></section><section class="form-section"><div class="settings-title"><Cpu/><div><h2>新建组默认值</h2><p>仅作用于以后创建的组。</p></div></div><label>默认客户端<el-select v-model="form.default_client_type"><el-option v-for="(v,k) in store.types" :key="k" :label="v.label" :value="k"/></el-select></label></section></div></el-tab-pane><el-tab-pane label="刷新与容错" name="refresh"><div class="settings-pane"><section class="form-section"><div class="settings-title"><Activity/><div><h2>刷新与容错</h2><p>控制并发、超时和 last-good。</p></div></div><div class="switch-row"><div><b>后台定时刷新</b><span>按组独立周期更新。</span></div><el-switch v-model="form.scheduler_enabled"/></div><div class="switch-row"><div><b>使用最后成功缓存</b><span>失败时继续保证客户端可用。</span></div><el-switch v-model="form.stale_cache_fallback"/></div><div class="switch-row"><div><b>跳过失败上游</b><span>其余来源继续生成。</span></div><el-switch v-model="form.skip_failed_upstreams"/></div><div class="form-grid"><label>上游超时<el-input-number v-model="form.upstream_timeout_seconds" :min="5" :max="180"/></label><label>转换超时<el-input-number v-model="form.converter_timeout_seconds" :min="20" :max="600"/></label><label>刷新并发<el-input-number v-model="form.scheduler_concurrency" :min="1" :max="10"/></label></div><label>User-Agent<el-input v-model="form.upstream_user_agent"/></label></section></div></el-tab-pane><el-tab-pane label="节点测活" name="health"><div class="settings-pane"><section class="form-section"><div class="settings-title"><Activity/><div><h2>真实代理测活</h2><p>分别判断基础连通和 Google 可用。</p></div></div><div class="switch-row"><div><b>自动测活</b><span>按周期测试全部启用组。</span></div><el-switch v-model="form.health_check_enabled"/></div><div class="form-grid"><label>周期（小时）<el-input-number v-model="form.health_check_interval_hours" :min="1" :max="168"/></label><label>并发数<el-input-number v-model="form.health_check_concurrency" :min="1" :max="20"/></label><label>超时（秒）<el-input-number v-model="form.health_check_timeout_seconds" :min="3" :max="30"/></label></div><div class="runtime-row"><span>基础目标</span><code>cp.cloudflare.com/generate_204</code></div><div class="runtime-row"><span>Google 目标</span><code>www.google.com/generate_204</code></div></section></div></el-tab-pane><el-tab-pane label="安全" name="security"><div class="settings-pane"><section class="form-section"><div class="settings-title"><UserRound/><div><h2>管理员账号</h2><p>变更后注销现有会话。</p></div></div><label>用户名<el-input v-model="form.admin_username"/></label><label>当前密码<el-input v-model="current_password" type="password" show-password/></label><div class="form-grid"><label>新密码<el-input v-model="new_password" type="password" show-password/></label><label>确认密码<el-input v-model="confirm_password" type="password" show-password/></label></div></section></div></el-tab-pane><el-tab-pane label="节点处理" name="nodes"><div class="settings-pane"><section class="form-section"><div class="settings-title"><ShieldCheck/><div><h2>节点过滤</h2><p>匹配的伪节点不会进入输出。</p></div></div><label>伪节点过滤正则<el-input v-model="form.pseudo_node_filter" type="textarea" :rows="7"/></label></section></div></el-tab-pane></el-tabs></div></section></template>
